import { Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent, IconChevronDown, IconArrowsMaximize,
  IconPlus, IconEdit, IconTrash, IconDownload, IconFilter, IconCheck,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import {
  HrmAppShell, HrmButton, HrmInput, HrmSelect, HrmOption, HrmTextarea, HrmSegmented, HrmDropdown,
  HrmListPage, HrmDataView, HrmGridColumn, HrmStatusCell, HrmActionCell, HrmActionItem,
  HrmDetailPeek, HrmPeekMode, HrmModalService,
} from 'hrm-ui';
import { SgTemplateSideNav } from './_template-side-nav';
import { SgTemplateContractMgmt } from './contract-mgmt-page';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';

/** 1 danh mục hệ thống (master data sau thiết lập). */
interface CatRow extends Record<string, unknown> {
  id: string; code: string; name: string; abbr: string; group: string; order: string;
  desc: string; note: string; module: string; editable: string; active: boolean; updated: string;
}

/** Doc page · Chế độ xem — Cơ bản danh mục (Template) — biến thể "danh sách 1 chế độ (Bảng)" của
 *  "Chế độ xem dữ liệu", KHÔNG segment. Nghiệp vụ QUẢN LÝ DANH MỤC: lưu master-data sau thiết lập
 *  (phòng ban, chức vụ, loại HĐ…) + trạng thái Hoạt động/Ngưng hoạt động. CRUD đủ: Thêm/Sửa (drawer)
 *  + Xoá có popup cảnh báo (HrmModalService.confirm danger). Self-contained, design token, component DS. */
@Component({
  selector: 'sg-template-catalog-basic',
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent, NzDropDownModule, NzMenuModule,
    HrmAppShell, SgTemplateSideNav, HrmButton, HrmInput, HrmSelect, HrmTextarea, HrmSegmented, HrmDropdown,
    HrmListPage, HrmDataView, HrmStatusCell, HrmActionCell, HrmDetailPeek,
    SgTemplateContractMgmt,
    SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" title="Chế độ xem — Cơ bản danh mục"
      desc="Biến thể 'danh sách 1 chế độ Bảng' (không segment) cho nghiệp vụ QUẢN LÝ DANH MỤC (master-data + trạng thái), CRUD đủ (Thêm/Sửa + Xoá cảnh báo). Trang minh hoạ 2 kiểu HEADER: Mẫu 1 — 1 tiêu đề (title-only); Mẫu 2 — header dạng tab (hrm-tabs) qua ví dụ Quản lý hợp đồng.">
      <div sgOverview>
        <!-- MẪU 1 — header 1 tiêu đề (title-only): danh mục master. -->
        <div class="smp-cap"><span class="smp-cap__n">Mẫu 1</span> Header 1 tiêu đề (title-only) — danh mục master.</div>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/catalog-basic" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>

        <!-- MẪU 2 — header dạng tab (hrm-tabs): nhúng nghiệp vụ Quản lý hợp đồng. -->
        <div class="smp-cap smp-cap--2"><span class="smp-cap__n">Mẫu 2</span> Header dạng tab (component <code>hrm-tabs</code>) — nghiệp vụ Quản lý hợp đồng.</div>
        <sg-template-contract-mgmt [embedded]="true" />
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/contract-mgmt" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>
      <div sgUsage>
        <sg-use purpose="Quản lý DANH MỤC (master-data) của hệ thống — dữ liệu cấu hình sau thiết lập, ít cột, cần CRUD nhanh + bật/tắt hiệu lực (Hoạt động/Ngưng hoạt động)."
          [when]="when"
          behavior="Danh sách 1 chế độ BẢNG (không đổi chế độ xem) + Tìm/Lọc trạng thái. Thêm danh mục / Sửa → mở drawer form (Mã, Tên, Mô tả, Trạng thái). Xoá → popup cảnh báo destructive, xác nhận mới xoá."
          avoid="Không dùng cho bản ghi nghiệp vụ có vòng đời/quy trình (dùng biến thể Đăng ký/Phê duyệt); không cần Thẻ/Kanban cho danh mục đơn giản." />
      </div>
      <div sgBest>
        <sg-do>Chỉ giữ 1 chế độ Bảng — danh mục ít cột, không cần segment đổi chế độ.</sg-do>
        <sg-do>Trạng thái Hoạt động/Ngưng hoạt động bằng <code>hrm-status-cell</code> (success/neutral).</sg-do>
        <sg-do>Xoá luôn có popup cảnh báo (<code>HrmModalService.confirm</code> danger) — tránh mất dữ liệu.</sg-do>
        <sg-do>Header linh hoạt: 1 tiêu đề (Mẫu 1) hoặc dạng tab <code>hrm-tabs</code> lọc lát cắt nghiệp vụ (Mẫu 2) — đặt tab trong slot <code>[lpTabs]</code>.</sg-do>
        <sg-dont>Đừng nhồi nhiều cột/nghiệp vụ phức tạp vào màn danh mục — giữ gọn.</sg-dont>
      </div>
    </sg-doc>
    }

    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <sg-template-side-nav appSideNav selectedKey="catalog" />

        <hrm-list-page title="Danh mục hệ thống"
          [total]="filteredRows().length" [(pageIndex)]="page" [pageSize]="10" [showSizeChanger]="true" [panel]="true">

          <!-- Header: KHÔNG segment (chỉ 1 chế độ Bảng), chỉ nút Thêm -->
          <div headerActions class="lp-hdr">
            <hrm-button variant="primary" (click)="openCreate()"><tabler-icon [icon]="plus" [size]="18" /> Thêm danh mục</hrm-button>
          </div>

          <div filters class="tbx">
            <hrm-input [(ngModel)]="kwModel" placeholder="Tìm mã, tên danh mục…" style="width:260px" />
            <!-- Filter nhanh trạng thái (đồng bộ VNR-HRE): nút "Trạng thái: X" → dropdown menu có đếm -->
            <button type="button" class="cf-fbtn" [class.cf-fbtn--on]="statusFilterModel !== 'all'"
              [hrmDropdown]="statusMenu" hrmDropdownTrigger="click" hrmDropdownPlacement="bottomLeft">
              <tabler-icon [icon]="filterIcon" [size]="16" />
              <span class="cf-fbtn__lbl">Trạng thái:</span>
              <span class="cf-fbtn__val">{{ statusCurrentLabel() }}</span>
              <tabler-icon class="cf-fbtn__chev" [icon]="chevDown" [size]="15" />
            </button>
          </div>
          <div actions class="tbx">
            <hrm-button variant="default"><tabler-icon [icon]="download" [size]="18" /> Xuất</hrm-button>
          </div>

          <hrm-data-view
            [columns]="cols()" [data]="filteredRows()" rowKey="id" tableMinWidth="760px"
            [modes]="['table']" mode="table" tableLabel="Bảng"
            (openRecord)="openEdit($any($event))" />

          <!-- Form Thêm/Sửa — CÙNG surface đa chế độ như 'Chế độ xem dữ liệu': master (cạnh bảng) ·
               side (drawer) · center (modal). Đồng bộ hrm-detail-peek của cả nhóm template list-page. -->
          <hrm-detail-peek lpDetail [(open)]="peekOpenModel" [(peekMode)]="peekModeModel"
            [modes]="['master','side','center','full','tab']" [expandable]="false"
            [title]="editingId() ? 'Sửa danh mục' : 'Thêm danh mục'"
            [content]="catFormTpl() ?? null" [footer]="catFooterTpl() ?? null" [modeLabels]="peekLabels"
            [routeUrl]="recordRoute"
            switchLabel="Đổi cách hiển thị" expandLabel="Mở toàn trang" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />

          <span pagerInfo>Hiển thị {{ filteredRows().length }} danh mục</span>
        </hrm-list-page>
      </hrm-app-shell>
    </ng-template>

    <!-- Ô Trạng thái -->
    <ng-template #statusCell let-row>
      <hrm-status-cell [status]="row.active ? 'success' : 'neutral'"
        [label]="row.active ? 'Hoạt động' : 'Ngưng hoạt động'" variant="badge" [dot]="true" />
    </ng-template>

    <!-- Ô Thao tác (Sửa · Xoá) -->
    <ng-template #actionsCell let-row>
      <hrm-action-cell [actions]="rowActions" [max]="2" (action)="onRowAction($any(row), $event)" />
    </ng-template>

    <!-- Menu filter nhanh trạng thái (mỗi mục = chấm màu + nhãn + đếm + tick) -->
    <nz-dropdown-menu #statusMenu="nzDropdownMenu">
      <ul nz-menu class="cf-menu">
        @for (f of STATUS_FILTERS; track f.value) {
          <li nz-menu-item (click)="statusFilterModel = f.value" [nzSelected]="statusFilterModel === f.value">
            <span class="cf-mdot" [style.background]="statusDot(f.value)"></span>
            <span class="cf-menu__t">{{ f.label }}</span>
            <span class="cf-menu__c">{{ countFor(f.value) }}</span>
            @if (statusFilterModel === f.value) { <tabler-icon class="cf-menu__ck" [icon]="check" [size]="15" /> }
          </li>
        }
      </ul>
    </nz-dropdown-menu>

    <!-- Form Thêm/Sửa danh mục — CONTENT của hrm-detail-peek (đa surface master/side/center). -->
    <ng-template #catForm>
      <div class="cf-body">
        <!-- Nhóm 1: Thông tin cơ bản -->
        <section class="cf-sec">
          <div class="cf-sec-h">Thông tin cơ bản</div>
          <div class="cf-grid">
            <label class="cf-field"><span class="cf-lbl">Mã danh mục</span>
              <hrm-input name="code" [(ngModel)]="form.code" placeholder="VD: DM11" /></label>
            <label class="cf-field"><span class="cf-lbl">Tên viết tắt</span>
              <hrm-input name="abbr" [(ngModel)]="form.abbr" placeholder="VD: PB" /></label>
            <label class="cf-field cf-field--full"><span class="cf-lbl">Tên danh mục <b class="cf-req">*</b></span>
              <hrm-input name="name" [(ngModel)]="form.name" placeholder="Nhập tên danh mục" /></label>
            <label class="cf-field"><span class="cf-lbl">Nhóm danh mục</span>
              <hrm-select name="group" [(ngModel)]="form.group" [options]="groupOptions" placeholder="Chọn nhóm" /></label>
            <label class="cf-field"><span class="cf-lbl">Thứ tự hiển thị</span>
              <hrm-input name="order" [(ngModel)]="form.order" placeholder="1" /></label>
            <label class="cf-field cf-field--full"><span class="cf-lbl">Trạng thái</span>
              <hrm-segmented [options]="statusSegs" [(ngModel)]="form.status" size="md" /></label>
          </div>
        </section>

        <!-- Nhóm 2: Mô tả & cấu hình -->
        <section class="cf-sec">
          <div class="cf-sec-h">Mô tả &amp; cấu hình</div>
          <div class="cf-grid">
            <label class="cf-field"><span class="cf-lbl">Áp dụng cho phân hệ</span>
              <hrm-select name="module" [(ngModel)]="form.module" [options]="moduleOptions" placeholder="Chọn phân hệ" /></label>
            <label class="cf-field"><span class="cf-lbl">Cho phép chỉnh sửa</span>
              <hrm-select name="editable" [(ngModel)]="form.editable" [options]="yesNoOptions" /></label>
            <label class="cf-field cf-field--full"><span class="cf-lbl">Mô tả</span>
              <hrm-textarea name="desc" [(ngModel)]="form.desc" placeholder="Mô tả ngắn gọn công dụng danh mục" /></label>
            <label class="cf-field cf-field--full"><span class="cf-lbl">Ghi chú</span>
              <hrm-textarea name="note" [(ngModel)]="form.note" placeholder="Ghi chú nội bộ (tuỳ chọn)" /></label>
          </div>
        </section>
      </div>
    </ng-template>

    <!-- FOOTER form — ghim đáy mọi surface (drawer/modal/master). -->
    <ng-template #catFooter>
      <div class="cf-foot">
        <hrm-button variant="default" (click)="peekOpen.set(false)">Huỷ</hrm-button>
        <hrm-button variant="primary" (click)="save()">{{ editingId() ? 'Lưu thay đổi' : 'Thêm danh mục' }}</hrm-button>
      </div>
    </ng-template>
  `,
  styles: [`
    .lp-desktop { position: relative; height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-desktop--full { position: relative; height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-full { margin-top: 14px; } .lp-full-link { text-decoration: none; }
    /* Caption phân tách 2 MẪU header trong cùng trang doc. */
    .smp-cap { margin: 4px 0 10px; font-size: var(--fs-13, 13px); color: var(--text-sub); }
    .smp-cap--2 { margin-top: 28px; }
    .smp-cap__n { display: inline-block; margin-right: 6px; padding: 1px 8px; border-radius: var(--radius-full, 999px); background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: var(--font-semibold, 600); }
    .lp-desktop ::ng-deep .shell-content { padding: 0; }

    .lp-hdr { display: flex; align-items: center; gap: var(--space-2, 8px); }
    .tbx { display: flex; align-items: center; gap: var(--space-2, 8px); flex-wrap: wrap; }
    /* Chỉ 1 chế độ Bảng → thanh mode-tabs của data-view rỗng nhưng vẫn chừa 12px (margin-bottom).
       Ẩn dv-bar rỗng để bảng sát toolbar, hết khoảng GAP trắng. */
    :host ::ng-deep hrm-data-view .dv-bar { display: none; }

    /* Peek body TỰ có padding 16 (dp-mbody/drawer/modal) — form đã tự padding qua .cf-body ⇒ ZERO
       padding vùng body khi chứa form (GIỐNG list-page :has(.ef)) để KHÔNG double-padding (chỉ còn 20px). */
    ::ng-deep .ant-drawer-body:has(.cf-body),
    ::ng-deep .ant-modal-body:has(.cf-body),
    ::ng-deep .dp-mbody:has(.cf-body) { padding: 0 !important; }

    /* Form trong hrm-detail-peek — CẤU TRÚC + MẬT ĐỘ khớp list-page (.ef-body/.ef-sec/.ef-grid 2 cột) */
    .cf-body { padding: var(--space-5, 20px) var(--space-5, 20px) var(--space-3, 12px); display: flex; flex-direction: column; gap: var(--space-6, 24px); }
    .cf-sec { display: flex; flex-direction: column; gap: var(--space-3, 12px); }
    .cf-sec-h { font-size: var(--fs-13, 13px); font-weight: var(--font-bold, 700); color: var(--text-strong); padding-bottom: 8px; border-bottom: 1px solid var(--border-soft); }
    .cf-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 16px; }
    .cf-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
    .cf-field--full { grid-column: 1 / -1; }
    .cf-lbl { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong); }
    .cf-req { color: var(--error-base); font-weight: var(--font-bold, 700); }
    .cf-foot { display: flex; justify-content: flex-end; gap: 10px; }

    /* Filter nhanh trạng thái (đồng bộ VNR-HRE .mr-fbtn) */
    .cf-fbtn { display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 12px; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); cursor: pointer; font: inherit; font-size: var(--fs-13, 13px); color: var(--text-body); white-space: nowrap; }
    .cf-fbtn:hover, .cf-fbtn--on { border-color: var(--primary-base); }
    .cf-fbtn > tabler-icon:first-child { color: var(--text-sub); }
    .cf-fbtn__lbl { font-weight: var(--font-medium, 500); color: var(--text-strong); }
    .cf-fbtn__val { color: var(--info-base); font-weight: var(--font-medium, 500); }
    .cf-fbtn__chev { color: var(--text-soft); }
    :host ::ng-deep .cf-menu .ant-dropdown-menu-item { display: flex; align-items: center; gap: 8px; }
    .cf-mdot { flex: none; width: 8px; height: 8px; border-radius: 50%; }
    .cf-menu__t { flex: 1; }
    .cf-menu__c { font-size: var(--fs-12, 12px); color: var(--text-soft); }
    .cf-menu__ck { color: var(--primary-base); }
  `],
})
export class SgTemplateCatalogBasic {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;
  private readonly modal = inject(HrmModalService);

  protected readonly maximize = IconArrowsMaximize;
  protected readonly chevDown = IconChevronDown;
  protected readonly plus = IconPlus;
  protected readonly download = IconDownload;
  protected readonly filterIcon = IconFilter;
  protected readonly check = IconCheck;
  protected readonly when = ['Quản lý master-data (phòng ban, chức vụ, loại HĐ…)', 'Bật/tắt hiệu lực danh mục (Hoạt động/Ngưng)', 'CRUD nhanh, ít cột, không cần đổi chế độ xem'];

  protected page = 1;

  // ── bộ lọc ──
  private _kw = signal(''); protected get kwModel() { return this._kw(); } protected set kwModel(v: string) { this._kw.set(v); }
  private _sf = signal('all'); protected get statusFilterModel() { return this._sf(); } protected set statusFilterModel(v: string) { this._sf.set(v); }
  /** Filter nhanh trạng thái (đồng bộ VNR-HRE): dropdown-button + menu có đếm. */
  protected readonly STATUS_FILTERS = [
    { value: 'all', label: 'Tất cả' }, { value: 'active', label: 'Hoạt động' }, { value: 'inactive', label: 'Ngưng hoạt động' },
  ];
  protected readonly statusCurrentLabel = computed(() => this.STATUS_FILTERS.find((f) => f.value === this._sf())?.label ?? 'Tất cả');
  protected statusDot(v: string): string { return v === 'active' ? 'var(--success-base)' : v === 'inactive' ? 'var(--text-sub)' : 'var(--text-soft)'; }
  protected countFor(v: string): number {
    const rs = this.rows();
    if (v === 'active') return rs.filter((r) => r.active).length;
    if (v === 'inactive') return rs.filter((r) => !r.active).length;
    return rs.length;
  }

  // ── cột bảng ──
  private readonly statusCell = viewChild.required<TemplateRef<any>>('statusCell');
  private readonly actionsCell = viewChild.required<TemplateRef<any>>('actionsCell');
  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'code', title: 'Mã', width: '90px', sortable: true },
    { key: 'name', title: 'Tên danh mục', width: '220px', sortable: true },
    { key: 'desc', title: 'Mô tả' },
    { key: 'active', title: 'Trạng thái', width: '160px', cell: this.statusCell() },
    { key: 'updated', title: 'Cập nhật', width: '120px' },
    { key: '__act', title: '', width: '84px', align: 'right', cell: this.actionsCell() },
  ]);
  protected readonly rowActions: HrmActionItem[] = [
    { key: 'edit', icon: IconEdit, label: 'Sửa' },
    { key: 'delete', icon: IconTrash, label: 'Xoá', danger: true },
  ];

  // ── STATE danh mục ──
  protected readonly rows = signal<CatRow[]>([
    { id: 'c1', code: 'DM01', name: 'Phòng ban', abbr: 'PB', group: 'org', order: '1', module: 'all', editable: 'yes', note: 'Đồng bộ với sơ đồ tổ chức', desc: 'Cơ cấu phòng ban / đơn vị trực thuộc', active: true, updated: '02/08/2026' },
    { id: 'c2', code: 'DM02', name: 'Chức vụ', abbr: 'CV', group: 'org', order: '2', module: 'all', editable: 'yes', note: '', desc: 'Chức danh công việc theo cấp bậc', active: true, updated: '02/08/2026' },
    { id: 'c3', code: 'DM03', name: 'Loại hợp đồng', abbr: 'LHĐ', group: 'hr', order: '3', module: 'hr', editable: 'yes', note: '', desc: 'Thử việc · Chính thức · Thời vụ · Cộng tác viên', active: true, updated: '28/07/2026' },
    { id: 'c4', code: 'DM04', name: 'Trình độ học vấn', abbr: 'TĐHV', group: 'hr', order: '4', module: 'hr', editable: 'yes', note: '', desc: 'Trung cấp · Cao đẳng · Đại học · Sau đại học', active: true, updated: '25/07/2026' },
    { id: 'c5', code: 'DM05', name: 'Loại nghỉ phép', abbr: 'LNP', group: 'time', order: '5', module: 'time', editable: 'yes', note: 'Ảnh hưởng công thức chấm công', desc: 'Phép năm · Nghỉ ốm · Thai sản · Không lương', active: true, updated: '20/07/2026' },
    { id: 'c6', code: 'DM06', name: 'Ngân hàng', abbr: 'NH', group: 'pay', order: '6', module: 'pay', editable: 'yes', note: '', desc: 'Danh sách ngân hàng trả lương', active: true, updated: '18/07/2026' },
    { id: 'c7', code: 'DM07', name: 'Ca làm việc', abbr: 'CLV', group: 'time', order: '7', module: 'time', editable: 'yes', note: '', desc: 'Ca sáng · Ca chiều · Ca đêm · Hành chính', active: true, updated: '15/07/2026' },
    { id: 'c8', code: 'DM08', name: 'Bậc lương', abbr: 'BL', group: 'pay', order: '8', module: 'pay', editable: 'no', note: 'Khóa sửa — đang rà soát thang bảng lương', desc: 'Thang bậc lương theo ngạch (đang rà soát)', active: false, updated: '10/07/2026' },
    { id: 'c9', code: 'DM09', name: 'Dân tộc', abbr: 'DT', group: 'hr', order: '9', module: 'all', editable: 'no', note: 'Danh mục chuẩn nhà nước', desc: 'Danh mục dân tộc', active: true, updated: '05/07/2026' },
    { id: 'c10', code: 'DM10', name: 'Lý do nghỉ việc', abbr: 'LDNV', group: 'hr', order: '10', module: 'hr', editable: 'yes', note: 'Ngưng dùng từ 2026', desc: 'Nhóm lý do nghỉ việc (cũ, ngưng dùng)', active: false, updated: '01/07/2026' },
  ]);
  protected readonly filteredRows = computed(() => {
    const kw = this._kw().trim().toLowerCase();
    const sf = this._sf();
    return this.rows().filter((r) => {
      if (sf === 'active' && !r.active) return false;
      if (sf === 'inactive' && r.active) return false;
      if (kw && !(`${r.code} ${r.name}`.toLowerCase().includes(kw))) return false;
      return true;
    });
  });

  // ── Form Thêm/Sửa qua hrm-detail-peek (surface master/side/center) — đồng bộ nhóm list-page ──
  protected readonly peekOpen = signal(false);
  protected get peekOpenModel(): boolean { return this.peekOpen(); }
  protected set peekOpenModel(v: boolean) { this.peekOpen.set(v); }
  protected readonly peekMode = signal<HrmPeekMode>('master');
  protected get peekModeModel(): HrmPeekMode { return this.peekMode(); }
  protected set peekModeModel(v: HrmPeekMode) { this.peekMode.set(v); }
  protected readonly peekLabels: Partial<Record<HrmPeekMode, string>> = { master: 'Cạnh bảng', side: 'Ngăn cạnh', center: 'Giữa màn hình', full: 'Toàn trang', tab: 'Tab mới' };
  protected readonly recordRoute = '/styleguide/hrm/template/catalog-basic';
  private readonly catFormTpl = viewChild<TemplateRef<any>>('catForm');
  private readonly catFooterTpl = viewChild<TemplateRef<any>>('catFooter');
  protected readonly editingId = signal<string | null>(null);
  protected form: { code: string; name: string; abbr: string; group: string; order: string; status: 'active' | 'inactive'; module: string; editable: string; desc: string; note: string } =
    { code: '', name: '', abbr: '', group: '', order: '', status: 'active', module: 'all', editable: 'yes', desc: '', note: '' };
  protected readonly statusSegs = [{ label: 'Hoạt động', value: 'active' }, { label: 'Ngưng hoạt động', value: 'inactive' }];
  protected readonly groupOptions: HrmOption[] = [
    { value: 'org', label: 'Tổ chức' }, { value: 'hr', label: 'Nhân sự' }, { value: 'time', label: 'Chấm công' }, { value: 'pay', label: 'Lương' }, { value: 'sys', label: 'Hệ thống' },
  ];
  protected readonly moduleOptions: HrmOption[] = [
    { value: 'all', label: 'Toàn hệ thống' }, { value: 'hr', label: 'Nhân sự' }, { value: 'time', label: 'Chấm công' }, { value: 'recruit', label: 'Tuyển dụng' }, { value: 'pay', label: 'Bảng lương' },
  ];
  protected readonly yesNoOptions: HrmOption[] = [{ value: 'yes', label: 'Có' }, { value: 'no', label: 'Không' }];
  private seq = 11;

  protected openCreate(): void {
    this.editingId.set(null);
    this.form = { code: `DM${String(this.seq).padStart(2, '0')}`, name: '', abbr: '', group: '', order: String(this.seq), status: 'active', module: 'all', editable: 'yes', desc: '', note: '' };
    this.peekOpen.set(true);
  }
  protected openEdit(row: CatRow): void {
    this.editingId.set(row.id);
    this.form = { code: row.code, name: row.name, abbr: row.abbr, group: row.group, order: row.order, status: row.active ? 'active' : 'inactive', module: row.module, editable: row.editable, desc: row.desc, note: row.note };
    this.peekOpen.set(true);
  }
  protected onRowAction(row: CatRow, key: string): void {
    if (key === 'edit') this.openEdit(row);
    else if (key === 'delete') this.confirmDelete(row);
  }
  protected save(): void {
    const f = this.form;
    const name = f.name.trim();
    if (!name) return;
    const active = f.status === 'active';
    const today = '04/08/2026';
    const patch = { code: f.code, name, abbr: f.abbr, group: f.group, order: f.order, module: f.module, editable: f.editable, desc: f.desc, note: f.note, active, updated: today };
    const id = this.editingId();
    if (id) {
      this.rows.update((rs) => rs.map((r) => (r.id === id ? { ...r, ...patch } : r)));
    } else {
      this.seq++;
      this.rows.update((rs) => [{ id: 'c' + (Date.now() % 100000), ...patch }, ...rs]);
    }
    this.peekOpen.set(false);
  }
  protected confirmDelete(row: CatRow): void {
    this.modal.confirm({
      title: `Xoá danh mục "${row.name}"?`,
      content: 'Danh mục và toàn bộ giá trị bên trong sẽ bị xoá. Hành động này không thể hoàn tác.',
      okText: 'Xoá', cancelText: 'Huỷ', danger: true,
      onOk: () => this.rows.update((rs) => rs.filter((r) => r.id !== row.id)),
    });
  }
}
